# Generated by dataset/sync.py — edit _shared/functional.py, not this copy.
"""Does this site work? — the generic half of every task's verifier.

Shared by every task and derived from nothing but the artifact. There is no
brief in here and no business name; each task adds those separately.

The organising idea: **hold the page to the promises its own markup makes.**

    <a href="x">          I lead somewhere
    <img src="x">         I will show you something
    <link rel=stylesheet> I change how this looks
    <form>                I accept input
    required              I will refuse to submit empty
    type="email"          I will refuse a non-address
    meta viewport         I work on a phone

Every check below asserts one of those declarations. Nothing is guessed and
nothing is task-specific, which is what makes it reusable — and what makes it
fair. We never wrote "check the Halden form"; we wrote "a form must accept
input", and it found the Halden form.

Two fairness rules, because an unsatisfiable check is a broken eval:

  * only assert against declarations that are actually present
  * honour anything the markup declares inert (`disabled`, `aria-disabled`)
    and skip anything off-origin, which an offline verifier cannot resolve

The site is served over HTTP from a **subpath**, never from the server root
and never over file://. At the root, `href="/styles.css"` resolves and the
bug hides; from a subpath it 404s, exactly as it does in the real preview.
"""

from __future__ import annotations

import http.server
import re
import shutil
import socket
import tempfile
import threading
from pathlib import Path
from urllib.parse import urlparse

MOUNT = "preview"

# Text that counts as telling the user something happened.
CONFIRMATION = re.compile(
    r"thank|thanks|received|in touch|we'll be|we will be|sent|submitted|booked|"
    r"on its way|got it|success",
    re.I,
)
# Text that counts as telling the user something is wrong.
COMPLAINT = re.compile(
    r"required|invalid|valid|must|please|cannot be empty|enter a|missing",
    re.I,
)


class Result:
    """One named metric, its score, and why."""

    def __init__(self) -> None:
        self.scores: dict[str, float] = {}
        self.notes: dict[str, str] = {}

    def record(self, name: str, passed: bool, note: str = "") -> bool:
        self.scores[name] = 1.0 if passed else 0.0
        if note:
            self.notes[name] = note
        print(f"[{'PASS' if passed else 'FAIL'}] {name}" + (f" — {note}" if note else ""), flush=True)
        return passed

    def skip(self, name: str, why: str) -> None:
        """Nothing declared this, so there is nothing to hold it to."""
        self.scores[name] = 1.0
        self.notes[name] = f"n/a: {why}"
        print(f"[ n/a ] {name} — {why}", flush=True)


# ------------------------------------------------------------------ serving
def free_port() -> int:
    with socket.socket() as sock:
        sock.bind(("127.0.0.1", 0))
        return sock.getsockname()[1]


def serve(site: Path):
    """Serve a copy of the site at http://127.0.0.1:PORT/preview/."""
    root = Path(tempfile.mkdtemp(prefix="verifier-serve-"))
    shutil.copytree(site, root / MOUNT)
    port = free_port()
    handler = type(
        "Handler",
        (http.server.SimpleHTTPRequestHandler,),
        {
            "__init__": lambda self, *a, **kw: http.server.SimpleHTTPRequestHandler.__init__(
                self, *a, directory=str(root), **kw
            ),
            "log_message": lambda *a, **kw: None,
        },
    )
    httpd = http.server.ThreadingHTTPServer(("127.0.0.1", port), handler)
    threading.Thread(target=httpd.serve_forever, daemon=True).start()
    return f"http://127.0.0.1:{port}/{MOUNT}", httpd, root


# ------------------------------------------------------------- page helpers
_WATCH = """
() => {
  window.__obs = {mutations: 0, requests: [], startUrl: location.href};
  new MutationObserver(m => { window.__obs.mutations += m.length; })
      .observe(document.body, {childList: true, subtree: true,
                              attributes: true, characterData: true});
  const of = window.fetch;
  window.fetch = (...a) => { window.__obs.requests.push(String(a[0])); return of(...a); };
  const os = XMLHttpRequest.prototype.open;
  XMLHttpRequest.prototype.open = function (m, u) {
    window.__obs.requests.push(String(u)); return os.apply(this, arguments);
  };
}
"""


def _watch(page) -> None:
    page.evaluate(_WATCH)


def _visible(page, selector: str) -> bool:
    """Is any element matching this selector actually on screen?"""
    for el in page.query_selector_all(selector):
        try:
            if el.is_visible():
                return True
        except Exception:
            continue
    return False


def _observed(page, page_path: str, requests: list[tuple[str, str]], before_text: str) -> dict:
    """Did anything happen that a user would notice?"""
    try:
        obs = page.evaluate("() => window.__obs || {mutations: 0, requests: []}")
    except Exception:
        obs = {"mutations": 0, "requests": []}

    # A POST or XHR to somewhere other than this page is a real submission.
    # A GET back to the same path with the answers in the query string is the
    # failure, not a success, so it must not count.
    offsite = [
        url for method, url in requests
        if urlparse(url).path != page_path and (method == "POST" or "/api" in url)
    ]
    offsite += [u for u in obs.get("requests", []) if urlparse(u).path != page_path]

    text_now = page.inner_text("body") if not page.is_closed() else ""
    gained = text_now.replace(before_text, "")
    navigated_away = urlparse(page.url).path != page_path

    echoed = "?" in page.url and not navigated_away

    # Two different questions, two different signals.
    #
    # `requests` answers "did the submission reach somewhere useful" — a POST
    # back to the page's own URL is not useful, so it is excluded above.
    #
    # `submitted` answers "was the submission attempted at all", which is
    # what validation is about. A POST to the page's own path still means the
    # browser let it through, so it counts here even though it does not count
    # above. Conflating the two made a `required` + `novalidate` form look
    # like it had refused.
    submitted = any(m == "POST" for m, _ in requests) or echoed or navigated_away

    return {
        "requests": offsite,
        "submitted": submitted,
        "mutations": obs.get("mutations", 0),
        # `query_selector` matches a hidden element, and a well-built page
        # ships its confirmation markup up front with `hidden` set. Presence
        # is therefore not evidence of anything — only visibility is. Getting
        # this wrong made a *correct* implementation fail validation_works,
        # because the check read the hidden success banner as an acceptance.
        "confirmed": _visible(page, "[role=status]") or bool(CONFIRMATION.search(gained)),
        "complained": _visible(page, "[role=alert]") or bool(COMPLAINT.search(gained)),
        "navigated": navigated_away,
        "echoed": echoed,
        "gained": gained[:200],
    }


def _fill(page, form_selector: str, email: str = "dana@example.com") -> int:
    """Fill a form's fields with plausible values. Returns how many."""
    filled = 0
    for el in page.query_selector_all(f"{form_selector} input, {form_selector} textarea, {form_selector} select"):
        kind = (el.get_attribute("type") or el.evaluate("e => e.tagName.toLowerCase()")).lower()
        if kind in {"hidden", "submit", "button", "reset", "image"}:
            continue
        name = ((el.get_attribute("name") or "") + " " + (el.get_attribute("id") or "")).lower()
        try:
            if kind == "select":
                values = el.evaluate("e => Array.from(e.options).map(o => o.value).filter(v => v)")
                if values:
                    el.select_option(values[0])
                    filled += 1
                continue
            if kind in {"checkbox", "radio"}:
                el.check()
                filled += 1
                continue
            if kind == "email" or "email" in name:
                value = email
            elif kind == "tel" or "phone" in name:
                value = "612-555-0148"
            elif kind == "date":
                value = "2026-09-14"
            elif kind == "number":
                value = "2"
            elif "name" in name:
                value = "Dana Whitfield"
            else:
                value = "Rear derailleur skipping under load."
            el.fill(value)
            filled += 1
        except Exception:
            pass
    return filled


def _submitter(page, form_selector: str):
    """The form's own submit control, if it has an enabled one."""
    for sel in ("button[type=submit]", "input[type=submit]", "button"):
        el = page.query_selector(f"{form_selector} {sel}")
        if el is None:
            continue
        if el.get_attribute("disabled") is not None:
            continue
        if (el.get_attribute("aria-disabled") or "").lower() == "true":
            continue
        return el
    return None


# ----------------------------------------------------------------- the suite
METRICS = ["renders", "controls_work", "validation_works", "responsive", "no_errors"]


def run(site: Path, result: Result) -> Result:
    """Run every generic check against the site. Populates `result`."""
    from playwright.sync_api import sync_playwright

    pages = sorted(p.name for p in site.glob("*.html"))
    if "index.html" not in pages:
        for m in METRICS:
            result.record(m, False, "no index.html")
        return result

    base, httpd, served = serve(site)
    try:
        with sync_playwright() as pw:
            browser = pw.chromium.launch(args=["--no-sandbox"])
            try:
                _renders(browser, base, pages, site, result)
                _controls(browser, base, result)
                _validation(browser, base, result)
                _responsive(browser, base, result)
            finally:
                browser.close()
    finally:
        httpd.shutdown()
        shutil.rmtree(served, ignore_errors=True)
    return result


def _instrument(page) -> tuple[list, list]:
    errors: list[str] = []
    requests: list[tuple[str, str]] = []
    page.on("pageerror", lambda e: errors.append(str(e)))
    page.on("console", lambda m: errors.append(f"console.error: {m.text}") if m.type == "error" else None)
    page.on("request", lambda r: requests.append((r.method, r.url)))
    return errors, requests


def _renders(browser, base: str, pages: list[str], site: Path, result: Result) -> None:
    """Every page loads, is styled, and its declared references resolve."""
    page = browser.new_page(viewport={"width": 1100, "height": 800})
    errors, _ = _instrument(page)
    problems: list[str] = []

    for name in pages:
        response = page.goto(f"{base}/{name}", wait_until="networkidle")
        if response is None or response.status >= 400:
            problems.append(f"{name} returned {response.status if response else 'nothing'}")
            continue
        if page.query_selector("h1") is None:
            problems.append(f"{name} rendered no <h1>")

        # A declared stylesheet must actually change how the page looks.
        if page.query_selector("link[rel=stylesheet]"):
            bg = page.evaluate("getComputedStyle(document.body).backgroundColor")
            if bg in {"rgba(0, 0, 0, 0)", "rgb(255, 255, 255)", ""}:
                problems.append(f"{name}: stylesheet declared but body background is {bg!r}")

        # A declared image must actually load.
        broken = page.evaluate(
            "() => Array.from(document.images)"
            ".filter(i => i.getAttribute('src') && !i.complete || i.naturalWidth === 0)"
            ".map(i => i.getAttribute('src'))"
        )
        if broken:
            problems.append(f"{name}: images did not load: {', '.join(broken[:3])}")

        # Same-origin links and in-page anchors must go somewhere real.
        dead = page.evaluate(
            "() => Array.from(document.querySelectorAll('a[href]'))"
            ".map(a => a.getAttribute('href'))"
            ".filter(h => h && h.startsWith('#') && h.length > 1 && !document.querySelector(h))"
        )
        if dead:
            problems.append(f"{name}: anchors point at nothing: {', '.join(dead[:3])}")

    result.record("renders", not problems, "; ".join(problems[:2]))
    result.record("no_errors", not errors, errors[0][:150] if errors else "")
    page.close()


def _controls(browser, base: str, result: Result) -> None:
    """Every form accepts input: submitting produces a request or feedback."""
    page = browser.new_page(viewport={"width": 1100, "height": 800})
    _, requests = _instrument(page)
    page.goto(f"{base}/index.html", wait_until="networkidle")

    forms = page.query_selector_all("form")
    if not forms:
        result.skip("controls_work", "the page declares no form")
        page.close()
        return

    page_path = urlparse(page.url).path
    problems: list[str] = []

    for index in range(len(forms)):
        selector = f"form:nth-of-type({index + 1})"
        page.goto(f"{base}/index.html", wait_until="networkidle")
        if page.query_selector(selector) is None:
            selector = "form"
        _watch(page)
        before = page.inner_text("body")
        filled = _fill(page, selector)
        submit = _submitter(page, selector)
        if submit is None:
            problems.append(f"form {index + 1} has no enabled submit control")
            continue

        requests.clear()
        submit.click()
        page.wait_for_timeout(2500)
        seen = _observed(page, page_path, requests, before)

        if seen["requests"] or seen["confirmed"]:
            continue
        if seen["echoed"]:
            problems.append(
                f"form {index + 1} reloaded the page with the answers in the query "
                f"string and showed nothing ({filled} fields filled)"
            )
        elif seen["navigated"]:
            problems.append(f"form {index + 1} navigated to {page.url} without confirming anything")
        else:
            problems.append(
                f"nothing happened on submit — no request, no confirmation "
                f"({filled} fields filled)"
            )

    result.record("controls_work", not problems, "; ".join(problems[:2]))
    page.close()


def _validation(browser, base: str, result: Result) -> None:
    """`required` refuses empty; `type=email` refuses a non-address.

    This is where a page can contradict itself in a way no diff shows:
    `required` on every field and `novalidate` on the form, with no script to
    compensate, means the validation is decorative.
    """
    page = browser.new_page(viewport={"width": 1100, "height": 800})
    _, requests = _instrument(page)
    page.goto(f"{base}/index.html", wait_until="networkidle")

    if page.query_selector("form") is None:
        result.skip("validation_works", "the page declares no form")
        page.close()
        return

    declares_required = page.query_selector("form [required]") is not None
    declares_email = page.query_selector("form input[type=email]") is not None
    if not (declares_required or declares_email):
        result.skip("validation_works", "the form declares no validation")
        page.close()
        return

    page_path = urlparse(page.url).path
    problems: list[str] = []

    def submits_anyway(label: str) -> bool:
        """True when the form let a bad value through."""
        submit = _submitter(page, "form")
        if submit is None:
            return False
        requests.clear()
        before = page.inner_text("body")
        _watch(page)
        submit.click()
        page.wait_for_timeout(1800)
        seen = _observed(page, page_path, requests, before)
        if seen["submitted"] or seen["confirmed"]:
            problems.append(f"{label} was accepted")
            return True
        # Chromium's native validation bubble is not in the DOM, so a block
        # with no visible message still counts as refusing.
        return False

    if declares_required:
        page.goto(f"{base}/index.html", wait_until="networkidle")
        submits_anyway("an empty form with required fields")

    if declares_email:
        page.goto(f"{base}/index.html", wait_until="networkidle")
        _fill(page, "form", email="notanemail")
        submits_anyway("an invalid email address")

    result.record("validation_works", not problems, "; ".join(problems[:2]))
    page.close()


def _responsive(browser, base: str, result: Result) -> None:
    """A page declaring a viewport must not overflow a phone."""
    page = browser.new_page(viewport={"width": 375, "height": 780})
    page.goto(f"{base}/index.html", wait_until="networkidle")
    if page.query_selector("meta[name=viewport]") is None:
        result.skip("responsive", "the page declares no viewport")
        page.close()
        return
    page.wait_for_timeout(300)
    size = page.evaluate(
        "() => ({s: document.documentElement.scrollWidth,"
        " c: document.documentElement.clientWidth})"
    )
    slack = size["s"] - size["c"]
    result.record("responsive", slack <= 1, "" if slack <= 1 else f"{slack}px of horizontal overflow at 375px")
    page.close()
